"use client"

import { useState } from "react"
import { XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, AreaChart, Area } from "recharts"
import { ChevronDown } from "lucide-react"

const mockDemandData = [
  { time: "00:00", demand: 4200, forecast: 4100 },
  { time: "04:00", demand: 3800, forecast: 3900 },
  { time: "08:00", demand: 6500, forecast: 6400 },
  { time: "12:00", demand: 7200, forecast: 7300 },
  { time: "16:00", demand: 7800, forecast: 7700 },
  { time: "20:00", demand: 8200, forecast: 8100 },
  { time: "24:00", demand: 5200, forecast: 5300 },
]

const mockStatesData = [
  { name: "Maharashtra", demand: 18500, trend: "+2.3%", status: "high" },
  { name: "Tamil Nadu", demand: 15200, trend: "+1.8%", status: "high" },
  { name: "Karnataka", demand: 12800, trend: "-0.5%", status: "medium" },
  { name: "Uttar Pradesh", demand: 21000, trend: "+3.1%", status: "high" },
  { name: "Gujarat", demand: 14200, trend: "+0.9%", status: "medium" },
]

export default function Dashboard() {
  const [selectedState, setSelectedState] = useState("Maharashtra")

  return (
    <div className="p-6 space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-4xl font-bold text-white mb-2">Electricity Demand</h1>
          <p className="text-blue-200">Real-time predictions for Indian states</p>
        </div>
        <div className="bg-blue-600 bg-opacity-20 border border-blue-400 border-opacity-30 rounded-lg px-6 py-3">
          <p className="text-sm text-blue-200">Last Updated</p>
          <p className="text-white font-semibold">2:45 PM IST</p>
        </div>
      </div>

      <div className="flex gap-4 items-center">
        <label className="text-white font-medium">Select State:</label>
        <div className="relative">
          <select
            value={selectedState}
            onChange={(e) => setSelectedState(e.target.value)}
            className="appearance-none bg-blue-600 bg-opacity-20 border border-blue-400 border-opacity-30 text-white rounded-lg px-4 py-2 pr-10 cursor-pointer hover:bg-opacity-30 transition"
          >
            {mockStatesData.map((state) => (
              <option key={state.name} value={state.name} className="bg-slate-900">
                {state.name}
              </option>
            ))}
          </select>
          <ChevronDown className="absolute right-3 top-2.5 w-5 h-5 text-blue-300 pointer-events-none" />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard label="Current Demand" value="18.5 GW" change="+2.3%" trend="up" />
        <MetricCard label="Peak Demand (Today)" value="21.2 GW" change="Peak at 7 PM" trend="info" />
        <MetricCard label="Available Supply" value="22.8 GW" change="+6.7%" trend="up" />
        <MetricCard label="Prediction Accuracy" value="94.2%" change="±2.1%" trend="neutral" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-6">
          <h2 className="text-white font-semibold mb-4">Demand vs Forecast (24h)</h2>
          <ResponsiveContainer width="100%" height={300}>
            <AreaChart data={mockDemandData}>
              <defs>
                <linearGradient id="colorDemand" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                </linearGradient>
                <linearGradient id="colorForecast" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#f59e0b" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#f59e0b" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
              <XAxis dataKey="time" stroke="rgba(255,255,255,0.5)" />
              <YAxis stroke="rgba(255,255,255,0.5)" />
              <Tooltip
                contentStyle={{
                  backgroundColor: "rgba(15, 23, 42, 0.95)",
                  border: "1px solid rgba(59, 130, 246, 0.5)",
                }}
              />
              <Legend wrapperStyle={{ color: "rgba(255,255,255,0.7)" }} />
              <Area
                type="monotone"
                dataKey="demand"
                stroke="#3b82f6"
                fillOpacity={1}
                fill="url(#colorDemand)"
                name="Actual Demand"
              />
              <Area
                type="monotone"
                dataKey="forecast"
                stroke="#f59e0b"
                fillOpacity={1}
                fill="url(#colorForecast)"
                name="Forecast"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-6">
          <h2 className="text-white font-semibold mb-4">Peak Hours</h2>
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <span className="text-sm text-blue-200">6 PM - 8 PM</span>
              <div className="flex items-center gap-2">
                <div className="w-20 h-2 bg-red-600 bg-opacity-30 rounded-full overflow-hidden">
                  <div className="w-4/5 h-full bg-red-500 rounded-full"></div>
                </div>
                <span className="text-white font-semibold text-sm">21.2 GW</span>
              </div>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sm text-blue-200">5 PM - 6 PM</span>
              <div className="flex items-center gap-2">
                <div className="w-20 h-2 bg-orange-600 bg-opacity-30 rounded-full overflow-hidden">
                  <div className="w-3/5 h-full bg-orange-500 rounded-full"></div>
                </div>
                <span className="text-white font-semibold text-sm">19.8 GW</span>
              </div>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sm text-blue-200">7 PM - 9 PM</span>
              <div className="flex items-center gap-2">
                <div className="w-20 h-2 bg-yellow-600 bg-opacity-30 rounded-full overflow-hidden">
                  <div className="w-1/2 h-full bg-yellow-500 rounded-full"></div>
                </div>
                <span className="text-white font-semibold text-sm">18.5 GW</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="bg-slate-800 bg-opacity-50 border border-blue-400 border-opacity-20 rounded-lg p-6">
        <h2 className="text-white font-semibold mb-4">States Overview</h2>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-blue-400 border-opacity-20">
                <th className="text-left py-3 px-4 text-blue-200 font-medium">State</th>
                <th className="text-right py-3 px-4 text-blue-200 font-medium">Current Demand</th>
                <th className="text-right py-3 px-4 text-blue-200 font-medium">Trend</th>
                <th className="text-center py-3 px-4 text-blue-200 font-medium">Status</th>
              </tr>
            </thead>
            <tbody>
              {mockStatesData.map((state, idx) => (
                <tr
                  key={idx}
                  className="border-b border-blue-400 border-opacity-10 hover:bg-blue-600 hover:bg-opacity-10 transition"
                >
                  <td className="py-3 px-4 text-white">{state.name}</td>
                  <td className="py-3 px-4 text-right text-blue-300 font-semibold">{state.demand} MW</td>
                  <td className="py-3 px-4 text-right">
                    <span className={state.trend.startsWith("+") ? "text-red-400" : "text-green-400"}>
                      {state.trend}
                    </span>
                  </td>
                  <td className="py-3 px-4 text-center">
                    <span
                      className={`px-3 py-1 rounded-full text-xs font-medium ${
                        state.status === "high"
                          ? "bg-red-600 bg-opacity-30 text-red-200"
                          : state.status === "medium"
                            ? "bg-yellow-600 bg-opacity-30 text-yellow-200"
                            : "bg-green-600 bg-opacity-30 text-green-200"
                      }`}
                    >
                      {state.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

function MetricCard({ label, value, change, trend }) {
  const trendColor = trend === "up" ? "text-red-400" : trend === "down" ? "text-green-400" : "text-blue-300"

  return (
    <div className="bg-blue-600 bg-opacity-20 border border-blue-400 border-opacity-30 rounded-lg p-4 hover:bg-opacity-30 transition">
      <p className="text-blue-200 text-sm mb-2">{label}</p>
      <p className="text-white text-3xl font-bold mb-1">{value}</p>
      <p className={`${trendColor} text-sm font-medium`}>{change}</p>
    </div>
  )
}
